      "中断服务开销为 (18+2) 条指令×5 周期/指令=100 个时钟周期/次。",
      "中断方式每秒中断次数：0.5 MB/s ÷ 4 B。按题库采用的 MB=10⁶ B，得到 125000 次/s。",
      "每秒 CPU 开销为 125000×100=12.5×10⁶ 周期，占比 12.5/500=2.5%。",
      "DMA 每块 5000 B，每秒块数为 5 MB/s ÷ 5000 B=1000 次/s；每次预处理与后处理共 500 周期。",
      "DMA 每秒开销为 1000×500=0.5×10⁶ 周期，占比 0.5/500=0.1%。DMA 将 CPU 占用从 2.5% 降至 0.1%。"
