  "信号量 P/V 操作": {
    "year": 2011,
    "index": 45,
    "id": 139,
    "typeName": "应用题",
    "score": 8,
    "answer": "mutex=1（取号机互斥），empty=10（空座位），full=0（等待顾客数），service=0（叫号同步）。顾客：P(empty); P(mutex); 取号; V(mutex); V(full); P(service); 接受服务。营业员：while(true){P(full); 叫号; V(empty); V(service); 为顾客服务;}。",
    "question": "某银行提供 1 个服务窗口和 10 个顾客等待座位。顾客到达银行时，若有空座位，则到取号机领取一个号，等待叫号。取号机每次仅允许一位顾客使用。当营业员空闲时，通过叫号选取一位顾客，并为其服务。顾客和营业员的活动过程描述如下： 请添加必要的信号量和 P、V（或 wait() 、 signal() ）操作实现上述过程的互斥和同步。要求写出完整的过程，说明信号量的含义并赋初值。",
    "analysis": "1）互斥资源：取号机（一次只一位顾客领号），因此设一个互斥信号量 mutex。 2）同步问题：顾客需要获得空座位等待叫号，当营业员空闲时，将选取一位顾客并为其服务。空座位的有、无影响等待顾客数量，顾客的有、无决定了营业员是否能开始服务，故分别设置信号量 empty 和 full 来实现这一同步关系。另外，顾客获得空座位后，需要等待叫号和被服务。这样，顾客与营业员就服务何时开始又构成了一个同步关系，定义信号量 service 来完成这一同步过程。 semaphore empty = 10; // 空座位的数量 semaphore mutex = 1; // 互斥使用取号机 semaphore full = 0; // 已占座位的数量 semaphore service = 0; // 等待叫号 process 顾客 i { P(empty); // 等空位 P(mutex); // 申请使用取号机 从取号机上取号; V(mutex); // 取号完毕 V(fu11); // 通知营业员有新顾客 P(service); // 等待营业员叫号 接受服务; } process 营业员 { while(True) ( P(fu11); // 没有顾客则休息 叫号; V(empty); // 离开座位 V(service); // 叫号 为顾客服务; } }",
    "steps": [
      "1）互斥资源：取号机（一次只一位顾客领号），因此设一个互斥信号量 mutex。",
      "2）同步问题：顾客需要获得空座位等待叫号，当营业员空闲时，将选取一位顾客并为其服务。",
      "空座位的有、无影响等待顾客数量，顾客的有、无决定了营业员是否能开始服务，故分别设置信号量 empty 和 full 来实现这一同步关系。",
      "另外，顾客获得空座位后，需要等待叫号和被服务。",
      "这样，顾客与营业员就服务何时开始又构成了一个同步关系，定义信号量 service 来完成这一同步过程。",
      "semaphore empty = 10; // 空座位的数量 semaphore mutex = 1; // 互斥使用取号机 semaphore full = 0; // 已占座位的数量 semaphore service = 0; // 等待叫号 process 顾客 i { P(empty); // 等空位 P(mutex); // 申请使用取号机 从取号机上取号; V(mutex); // 取号完毕 V(fu11); // 通知营业员有新顾客 P(service); // 等待营业员叫号 接受服务; } process 营业员 { while(True) ( P(fu11); // 没有顾客则休息 叫号; V(empty); // 离开座位 V(service); // 叫号 为顾客服务; } }"
    ],
    "stepsSource": "source",
    "topic": "操作系统",
    "matchKind": "直接考点",
    "teachingSteps": [
      "先识别资源与同步关系：10 个等待座位、1 台取号机、顾客到达事件、营业员叫号服务事件。",
      "定义 empty=10 表示空座位数；full=0 表示等待服务的顾客数；mutex=1 保护取号机；service=0 表示等待被叫号的顾客数。",
      "顾客流程：P(empty) 占座；P(mutex) 进入取号机临界区并取号；V(mutex) 释放取号机；V(full) 通知营业员有顾客；P(service) 等待叫号。",
      "营业员流程：P(full) 等待顾客；叫号；V(empty) 释放一个等待座位；V(service) 唤醒一位顾客接受服务。",
      "检查同步：无顾客时营业员阻塞在 P(full)；无空座时新顾客阻塞在 P(empty)；取号机由 mutex 保证互斥。"
    ],
    "audit": {
      "status": "cross-checked",
      "note": "与2011年真题公开参考答案的四个信号量、初值及P/V顺序核对一致。"
    }
  },
