    "question": "若系统 S1 采用死锁避免方法，S2 采用死锁检测方法。下列叙述中，正确的是（）。 Ⅰ、S1 会限制用户申请资源的顺序，而 S2 不会 Ⅱ、S1 需要进程运行所需的资源总量信息，而 S2 不需要 Ⅲ、S1 不会给可能导致死锁的进程分配资源，而 S2 会 A. 仅Ⅰ、Ⅱ B. 仅Ⅱ、Ⅲ C. 仅Ⅰ、Ⅲ D. Ⅰ、Ⅱ、Ⅲ",
    "analysis": "死锁处理 采用三种策略：死锁预防、死锁避免、死锁检测和解除。 死锁预防，采用破坏产生死锁的四个必要条件中的一个或几个，以防止发生死锁。其中之一的“破坏循环等待条件”，一般采用顺序资源分配法，首先给系统的资源编号，规定每个进程必须按编号递增的顺序请求资源，也就是限制了用户申请资源的顺序，故 I 的前半句属于死锁预防的范畴。 银行家算法是最著名的死锁避免算法，其中的最大需求矩阵 MAX 定义了每一个进程对 m 类资源的最大需求量，系统在执行安全性算法中都会检查此次资源试分配后，系统是否处于安全状态，若不安全则将本次的试探分配作废。 在死锁的检测和解除中，在系统为进程分配资源时不采取任何措施，但提供死锁的检测和解除的手段。故 II、III 正确。",
