      "两台主机均检测到冲突的时间最长： T ( b ) ​ = 2 km /200000 km / s × 2 = 0.02 m s = 双程传播时延 2 t 0 ​ 甲 甲 乙 乙 甲 乙 甲 甲 乙 乙 甲 乙 (a) 时间最短的情况 (b) 时间最长的情况 2）甲发送一个数据帧的时间，即发送时延 t 1 ​ = 1518 × 8 bi t / ( 10 M b p s ) = 1.2144 m s ；",
      "乙每成功收到一个数据帧后，向甲发送一个确认帧，确认帧的发送时延 t 2 ​ = 64 × 8 bi t /10 M b p s = 0.0512 m s ；",
