    "score": 9,
    "answer": "（1）卫星传播距离为地面→卫星→地面，共2×36000km，单向传播时延=0.24s；瓶颈链路速率200kbps；4000B文件发送时延=4000×8/200000=0.16s，总时间至少0.40s。（2）帧发送时延Tf=1500×8/200000=0.06s，RTT=0.48s。忽略ACK帧长度，ACK发送时延为0，U=W×Tf/(RTT+Tf)≥0.8，W≥0.8×0.54/0.06=7.2，故窗口至少8。GBN序号空间至少W+1=9，故序号字段至少4位。（3）管理区主机10.10.10.33/26所在网络为10.10.10.0/26；作业区为10.10.10.64/26，生活区为10.10.10.128/25。可用主机范围分别为.65–.126和.129–.254。",
    "question": "408真题系统 TR1 作业区子网 生活区子网 管理区子网 S1 H 10.10.10.33/26 TR1 R1 Internet R2 总部服务器 工程部网络 卫星 轨道高度 36000km，电磁波速度 300000 km/s TR1 和 TR2 为全双工调制解调设备， 卫星链路为 R1, R2 之间提供对称全双工信号，每个方向数据传输率为 200kbps (1) 忽略卫星信号中继，TR1，TR2 调制解调开销，则 R1 到 R2 之间的卫星链路单向传播时延是多少？主机 H 向总部服务器传输数据时可达到的最大吞吐量是多少？若忽略各层协议首部开销，以及以太网的传播时延，则 H → server 上传一个 4000B 的文件，至少需要多长时间？ (2) 基于 GBN 为卫星链路设计单向可靠的链路层协议 SLP，支持 R1 → R2 发送数据。SLP 数据帧长 1500B，忽略 ACK 帧长度，要求 SLP 单向信道利用率不低于 80%，则发送窗口至少为？SLP 帧序号至少为多少？ (3) 总部给工程部分配 IP 地址空间 10.10.10.0/24，再划分为 3 个子网：管理区子网、生活区子网、作业区子网。已知管理区子网地址为 10.10.10.33/26，若生活区子网不少于 120 个，作业子网、管理区子网 IP 均不少于 60 个，H 已正确配置 IP。请问作业区子网和生活区子网地址各是多少？",
    "analysis": "（1）卫星链路经地面→卫星→地面两段传播，单向时延 Tp=2×36000/300000=0.24s。最大吞吐量受200kbps卫星链路限制。4000B文件发送时延=4000×8/200000=0.16s，故至少0.40s。（2）数据帧发送时延 Tf=1500×8/200000=0.06s，RTT=0.48s。题干忽略ACK帧长度，因此ACK发送时延Ta=0。GBN单向利用率 U=W×Tf/(RTT+Tf)，要求 U≥0.8，得 W≥0.8×(0.48+0.06)/0.06=7.2，发送窗口至少8。GBN接收窗口为1，序号空间至少W+1=9，故帧序号至少4位。（3）10.10.10.33/26是管理区主机地址，其所在网络为10.10.10.0/26；作业区分配10.10.10.64/26，生活区分配10.10.10.128/25。可用地址范围分别为10.10.10.65–10.10.10.126及10.10.10.129–10.10.10.254。",
