      "因此，R1 和 R2 之间的卫星链路的 单向传播时延 可以计算为：时延 = 2×距离/速度 = 2×36000km/(300000km/s) = 0.24 秒 。",
      "计算传播时延注意需要 × 2，因为需要通过卫星中转，首先地面 → 卫星，然后卫星 → 地面 计算主机 H 向总部服务器可达到的最大传输量：最大吞叶量与链路带宽和传播时延相关。",
