    "question": "假定计算机的主频为 500MHz，CPI 为 4。现有设备 A 和 B，其数据传输率分别为 2MBps 和 40MBps，对应 I/O 接口中各有一个 32 位数据缓冲寄存器。请回答下列问题，要求给出计算过程。 (1) 若设备 A 采用定时查询 I/O 方式，每次输入/输出都至少执行 10 条指令。设备 A 最多间隔多长时间查询一次才能不丢失数据？CPU 用于设备 A 输入/输出的时间占 CPU 总时间的百分比至少是多少？ (2) 在中断 I/O 方式下，若每次中断响应和中断处理的总时钟周期数至少为 400，则设备 B 能否采用中断 I/O 方式？为什么？ (3) 若设备 B 采用 DMA 方式，每次 DMA 传送的数据块大小 1000B，CPU 用于 DMA 预处理和后处理的总时钟周期数为 500，则 CPU 用于设备 B 输入/输出的时间占 CPU 总时间的百分比最大是多少？",
    "analysis": "A设备每次传输4B，2MB/s对应每秒500000次查询。每次查询至少执行10条指令，CPI=4，耗时40/500MHz=80ns，CPU占用率为500000×80ns=4%。B设备40MB/s对应每秒10000000次中断，每次400周期，在500MHz下每次0.8μs，合计CPU需求800%，因此不能采用中断I/O。DMA每块1000B，每秒40000块，每块CPU开销500周期即1μs，CPU占用率4%。",
