      "平均旋转等待=(60/7200)/2=4.167ms；单扇区传输时间=(60/7200)/500=0.0167ms；总访问时间=5+4.167+0.0167≈9.18ms。",
      "64位=8B；512B/8B=64次DMA请求。",
      "周期挪用时DMA需及时处理设备缓冲区请求，通常优先取得总线。"
