    "score": 14,
    "answer": "(1) 数组占2页，产生2次缺页，故障地址为00422000H和00423000H。(2) 数组写入仅一次，缺少时间局部性，但行优先访问具有空间局部性。(3) 块内地址A4~A0，组号A10~A5；a[1][0]=00422100H，组号8。(4) 数组占192个主存块；两种循环顺序在给定4路组相联Cache中命中率均为87.50%。",
    "question": "已知计算机 M 字长为 32 位，按字节编址，采用请求调页策略的虚拟存储管理方式，虚拟地址为 32 位，页面大小为 4KB；数据 Cache 采用 4 路组相联映射，数据区大小为 8KB，主存块大小为 32B。现有 C 语言程序段如下： for ( i = 0 ; i < 24 ; i ++ ) for ( j = 0 ; j < 64 ; j ++ ) a [ i ][ j ] = 10 ; 已知二维数组 a 按行优先存放，在虚拟地址空间中分配的起始地址为 0042 2000H，sizeof(int)=4，假定在 M 上执行上述程序段之前数组 a 不在主存，且在该程序段执行过程中不会发生页面置换。请回答下列问题。 (1) 数组 a 分为几个页面存储？对于数组 a 的访问，会发生几次缺页异常？页故障地址各是什么？ (2) 不考虑变量 i 和 j，该程序段的数据访问是否具有时间局部性？为什么？ (3) 计算机 M 的虚拟地址（A31~A0）中哪几位用作块内地址？哪几位用作 Cache 组号？a[1][0] 的虚拟地址是多少？其所在主存块对应的 Cache 组号是多少？ (4) 数组 a 占用多少主存块？假设上述程序段执行过程中数组 a 的访问不会和其他数据发生 Cache 访问冲突，则数组 a 的 Cache 命中率是多少？若将循环中 i 和 j 的次序按如下方式调换： for ( j = 0 ; j < 64 ; j ++ ) for ( i = 0 ; i < 24 ; i ++ ) a [ i ][ j ] = 10 ; 则数组 a 的 Cache 命中率又是多少？",
    "analysis": "数组大小24×64×4=6144B，页大小4096B，起始地址00422000H页对齐，跨两个页面，首次访问每页各产生一次缺页。32B块需要5位块内偏移；8KB/32B=256块，4路组相联共有64组，需要6位组号，故为A10~A5。a[1][0]地址为00422000H+256=00422100H，组号为8。数组共6144/32=192块。Cache有256行，数组工作集可容纳；每个块8个int，按行或按列遍历时每块均首次缺失一次、随后7次命中，因此命中率均为7/8=87.5%。",
    "steps": [
      "数组字节数=24×64×4=6144B，跨越00422000H和00423000H两个4KB页面，缺页2次。",
      "块大小32B，块内偏移5位；Cache共有8192/32/4=64组，组号6位，即A10~A5。",
      "a[1][0]地址=00422000H+1×64×4=00422100H；组号=(地址>>5)&63=8。",
      "数组占6144/32=192块；每块含8个int，Cache共256行且无冲突，按两种循环顺序均为每8次访问1次缺失，命中率87.5%。"
    ],
