    "typeName": "应用题",
    "score": 8,
    "answer": "(1) <0,4>→页框21。(2) <1,11>→页框32。(3) <2,14>→页框41。(4) 该策略倾向保留近期访问页，能利用时间局部性；窗口过短时也可能提前回收即将重用的页。",
    "question": "某请求分页系统的局部页面置换策略如下：系统从 0 时刻开始扫描，每隔 5 个时间单位扫描一轮驻留集（扫描时间忽略不计），本轮没有被访问过的页框将被系统回收，并放入到空闲页框链尾，其中内容在下一次被分配之前不被清空。当发生缺页时，如果该页曾被使用过且还在空闲页框链表中，则重新放回进程的驻留集中；否则，从空闲页框链表头部取出一个页框。 假设不考虑其他进程的影响和系统开销，初始时进程驻留集为空。目前系统空闲页框链表中页框号依次为 32、15、21、41。进程 P 依次访问的 <虚拟页号，访问时刻> 是： <1, 1>、<3, 2>、<0, 4>、<0, 6>、<1, 11>、<0, 13>、<2, 14>。请回答下列问题。 (1) 访问<0, 4>时，对应的页框号是什么？ (2) 访问<1, 11>时，对应的页框号是什么？说明理由。 (3) 访问<2, 14>时，对应的页框号是什么？说明理由。 (4) 该策略是否适合于时间局部性好的程序？说明理由。",
    "analysis": "初始空闲页框队列为32、15、21、41。t=1、2、4分别为页1、页3、页0分配页框32、15、21。t=5扫描时三页在本轮均被访问，保留；t=6再次访问页0。t=10扫描时页1、页3在本轮未访问，被回收并按扫描次序追加到空闲队列尾，页0保留。t=11访问页1时，其内容仍在空闲队列中，复用页框32；t=13页0仍在页框21；t=14页2首次缺页，从空闲队列头部取得页框41。",
