    "typeName": "应用题",
    "score": 8,
    "answer": "P1：x=produce(); P(empty); P(mutex); put(x); if (x%2) V(odd); else V(even); V(mutex)。P2：P(odd); P(mutex); x=getodd(); countodd(); V(mutex); V(empty)。P3：P(even); P(mutex); x=geteven(); counteven(); V(mutex); V(empty)。初值：mutex=1，empty=N，odd=even=0。",
    "question": "2009-Question-45-questions 三个进程 P 1 ​ 、 P 2 ​ 、 P 3 ​ 互斥使用一个包含 N ( N > 0 ) 个单元的缓冲区。 P 1 ​ 每次用 produce() 生成一个正整数并用 put() 送入缓冲区某一空单元中； P 2 ​ 每次用 getodd() 从该缓冲区中取出一个奇数并用 countodd() 统计奇数个数； P 3 ​ 每次用 geteven() 从该缓冲区中取出一个偶数并用 counteven() 统计偶数个数。请用信号量机制实现这三个进程的同步与互斥活动，并说明所定义信号量的含义。要求用伪代码描述。",
    "analysis": "设 mutex=1 保护缓冲区互斥访问，empty=N 表示空缓冲区单元数，odd=0、even=0 分别表示缓冲区中可取的奇数和偶数个数。P1 放入数据后按奇偶性释放对应计数信号量；P2、P3 分别等待对应类型数据，取出后释放 empty。",
    "steps": [
      "初始化 mutex=1、empty=N、odd=0、even=0。",
      "P1：x=produce(); P(empty); P(mutex); put(x); 若 x 为奇数则 V(odd)，否则 V(even)；V(mutex)。",
      "P2：P(odd); P(mutex); x=getodd(); countodd(); V(mutex); V(empty)。",
      "P3：P(even); P(mutex); x=geteven(); counteven(); V(mutex); V(empty)。",
      "empty 保证不向满缓冲区写入；odd/even 保证消费者只在相应数据存在时取数；mutex 保证对缓冲区的互斥访问。"
    ],
