    "question": "2010-第21题-题目 单级中断系统中，中断服务程序内的执行顺序是（ ）。 I 保护现场 II 开中断 III 关中断 IV 保存断点 V 中断事件处理 VI 恢复现场 VII 中断返回 A. I→V→VI→II→VII B. III→I→V→VII C. III→IV→V→VI→VII D. IV→I→V→VI→VI",
