    "answer": "D",
    "question": "2023-第33题-题目 如图，2 段链路的数据传输速率为 100Mbps，时延带宽积（即单向传播时延*带宽）均为 1000bit。若 H1 向 H2 发送 1 个大小为 1MB 的文件，分组长度为 1000B，则从 H1 开始发送时刻起到 H2 收到文件全部数据时刻止，所需的时间至少是（注： M = 1 0 6 ）? 408真题系统 R H1 H2 L1 L2 A. 80.02ms B. 80.08ms C. 80.09ms D. 80.10ms",
    "analysis": "每段链路的单向传播时延为 1000bit/100Mbps=10μs；每个 1000B 分组的发送时延为 8000bit/100Mbps=80μs。两段链路采用存储转发，首个分组到达 H2 需 2×(80+10)=180μs；流水线填满后，其余 999 个分组每 80μs 到达一个。总时间为 180μs+999×80μs=80.10ms，选 D。",
    "steps": [
      "每段传播时延 τ=1000/100×10^6=10μs。",
      "每个分组发送时延 t=1000×8/100Mbps=80μs。",
      "存储转发下首个分组经过两段链路：2×(80+10)=180μs。",
      "共有 1MB/1000B=1000 个分组，流水线填充后剩余 999 个分组每 80μs 完成一个。",
      "总时延=180μs+999×80μs=80100μs=80.10ms，选 D。"
    ],
