    "index": 43,
    "id": 654,
    "typeName": "应用题",
    "score": 10,
    "answer": "(1) SF=F15；加法溢出 OF=(¬A15∧¬B15∧F15)∨(A15∧B15∧¬F15)；减法溢出 OF=(A15∧¬B15∧¬F15)∨(¬A15∧B15∧F15)。(2) Y 暂存 ALU 一个输入操作数，Z 暂存 ALU 运算结果，适配单总线数据通路。(3) rs、rd 为 4 位，最多 16 个通用寄存器；字段来自 IR，rs 控制读多路选择器，rd 控制写地址译码器。(4) PCout、MARin；Read 保持 5 个时钟周期并在数据到达时 MDRinE；随后 MDRout、IRin，至少 7 个时钟周期。(5) 控制信号由控制器 CU 产生，IR 和 FR 的输出连接到 CU 输入。",
    "question": "2022-第43题-题目 某 CPU 中部分数据通路如图所示，其中，GPRs 为通用寄存器组；FR 为标志寄存器，用于存放 ALU 产生的标志信息；带箭头虚线表示控制信号，如控制信号 ReaD. Write 分别表示主存读、主存写，MDRin 表示内部总线上数据写入 MDR，MDRout 表示 MDR 的内容送内部总线。 408真题系统 MAR MARin MDR MDRin MDRout PC PCin PCout IR IRin 送 CU 等部件 Read Write 内部总线 主 存 储 器 Y ALU Yin Z SF OF ··· FR ALUop Zout GPRs rd GPRin rs GPRout 4 4 16 16 16 A B F (1) ALU 的输入端 A. B 及输出端 F 的最高位分别为 A15 、 B15 及 F15 ，FR 中的符号标志和溢出标志分别为 SF 和 OF，则 SF 的逻辑表达式是什么？A 加 B. A 减 B 时 OF 的逻辑表达式分别是什么？要求逻辑表达式的输入变量为 A15、B15 及 F15 。 (2) 为什么要设置暂存器 Y 和 Z？ (3) 若 GPRs 的输入端 rs、rd 分别为所读、写的通用寄存器的编号，则 GPRs 中最多有多少个通用寄存器？rs 和 rd 来自图中的哪个寄存器？已知 GPRs 内部有一个地址译码器和一个多路选择器，rd 应该连接地址译码器还是多路选择器？ (4) 取指令阶段（不考虑 PC 增量操作）的控制信号序列是什么？若从发出主存读命令到主存读出数据并传送到 MDR 共需 5 个时钟周期，则取指令阶段至少需要几个时钟周期？ (5) 图中控制信号由什么部件产生？图中哪些寄存器的输出信号会连到该部件的输入端？",
    "analysis": "该题综合考查 ALU 符号/溢出标志、单总线数据通路暂存、寄存器组读写端口、取指控制序列和控制器输入。符号标志直接取结果最高位；溢出需判断操作数符号与结果符号；寄存器编号字段来自 IR；控制器依据指令和状态标志产生控制信号。",
    "steps": [
      "(1) SF=F15。加法溢出：两个操作数同号而结果异号，OF=(¬A15∧¬B15∧F15)∨(A15∧B15∧¬F15)。减法溢出：操作数异号且结果符号与 A 不同，OF=(A15∧¬B15∧¬F15)∨(¬A15∧B15∧F15)。",
      "(2) 单总线结构同一时刻通常只能有一个部件驱动总线。Y 暂存 ALU 的一个输入操作数，Z 暂存 ALU 结果，便于分时完成运算和写回。",
      "(3) rs、rd 各 4 位，故寄存器数最多 2^4=16。字段来自 IR；rs 选择读端口多路选择器，rd 选择写入目标的地址译码器。",
      "(4) 先 PCout、MARin 将 PC 送入 MAR；发出 Read，等待 5 个时钟周期并在数据到达时用 MDRinE 将主存数据写入 MDR；再 MDRout、IRin 将指令送入 IR。至少 1+5+1=7 个时钟周期。",
      "(5) 控制信号由控制器 CU 产生；IR 提供操作码等指令字段，FR 提供条件标志，二者输出连接到 CU 输入。"
    ],
