      "128KB/2B=64K 个字地址，需要 16 位 MAR；一个字长 16 位，MDR 至少 16 位。",
      "相对偏移寄存器为 16 位补码，表示范围 −32768～32767 个字地址，目标为 PC+(Rn)。",
      "编码：OP=0010，Ms=001，Rs=100，Md=010，Rd=101，拼接为 0010001100010101B=2315H。",
      "源操作数 M[R4]=M[1234H]=5678H；目的操作数原值 M[R5]=M[5678H]=1234H。相加得 68ACH，写回 M[5678H]。",
