    "typeName": "应用题",
    "score": 8,
    "answer": "(1) 采用连续分配更合适。文件一次写入后不可修改，创建时可确定所需空间；连续分配便于顺序和随机访问，且没有后续扩展导致的外部碎片搬移问题。FCB 至少记录起始物理块号和文件长度（块数/字节数），还可记录文件名及属性。(2) 为快速查找文件，FCB 集中存储在目录区更合适；可对目录项按文件名建立索引或散列，避免逐个数据区查找。",
    "question": "2011-第46题-题目 某文件系统为一级目录结构，文件的数据一次性写入磁盘，已写入的文件不可修改，但可多次创建新文件。请回答如下问题∶ (1) 在连续、链式、索引二种文件的数据块组织方式中。哪种更合适？要求说明理由。为定位文件数据块，需要在 FCB 中设计哪些相关描述字段？ (2) 为快速找到文件，对于 FCB，是集中存储好，还是与对应的文件数据块连续存储好？要求说明理由。",
    "analysis": "文件创建时一次性写入且之后不可修改，适合在创建时一次分配连续空间；连续分配具有较好的顺序访问和直接定位性能。FCB 集中存放在目录区便于通过目录索引快速检索，数据块只需按 FCB 中的起始块号和长度定位。",
    "steps": [
      "比较分配方式：链式访问需沿指针遍历，索引分配需要索引块；连续分配可按起始块号和偏移直接定位。",
      "文件不可修改且一次写入，创建时可确定大小并一次性分配连续块，后续不需要扩展。",
      "FCB 记录起始块号、文件长度/占用块数，以及文件名等目录属性。",
      "为快速查找文件，将 FCB 集中放在目录区，并可按文件名建立索引；不必到各数据区逐个搜索。"
    ],
