    "question": "2012-第10题-题目 在内部排序过程中，对尚未确定最终位置的所有元素进行一遍处理称为一趟排序。下列排序方法中，每一趟排序结束都至少能够确定一个元素最终位置的方法是（ ）。 Ⅰ．简单选择排序 Ⅱ．希尔排序 Ⅲ．快速排序 Ⅳ．堆排序 Ⅴ．二路归并排序 A. 仅Ⅰ、Ⅲ、Ⅳ B. 仅Ⅰ、Ⅲ、Ⅴ C. 仅Ⅱ、Ⅲ、Ⅳ D. 仅Ⅲ、Ⅳ、Ⅴ",
    "analysis": "简单选择排序每趟把最小（或最大）元素放到最终位置；快速排序每次分区确定枢轴最终位置；堆排序每趟将堆顶元素放入有序区。希尔排序和二路归并排序每趟不保证至少一个元素到达最终位置，故为Ⅰ、Ⅲ、Ⅳ，选 A。",
    "steps": [
      "Ⅰ简单选择排序：每趟选择极值放到有序区边界，位置最终确定。",
      "Ⅱ希尔排序：一趟 h-排序只保证分组有序，不保证某个元素已处于全局最终位置。",
      "Ⅲ快速排序：一次 partition 确定枢轴的最终位置。",
      "Ⅳ堆排序：每趟取出堆顶极值放入最终有序区。",
      "Ⅴ二路归并排序：每趟形成有序段，但元素最终位置可能在后续归并中改变。",
      "因此选择Ⅰ、Ⅲ、Ⅳ，选 A。"
    ],
