    "score": 2,
    "answer": "A",
    "question": "2015-第39题-题目 主机甲和主机乙新建一个 TCP 连接，甲的拥塞控制初始阈值为 32KB，甲向乙始终以 MSS=1KB 大小的段发送数据，并一直有数据发送；乙为该连接分配 16KB 接收缓存，并对每个数据段进行确认，忽略段传输延迟。若乙收到的数据全部存入缓存，不被取走，则甲从连接建立成功时刻起，未发生超时的情况下，经过 4 个 RTT 后，甲的发送窗口是（ ）。 A. 1KB B. 8KB C. 16KB D. 32KB",
    "analysis": "发送窗口取拥塞窗口 cwnd 与接收窗口 rwnd 的较小值。初始 cwnd=1KB，慢启动每 RTT 翻倍，4 个 RTT 后 cwnd=16KB。接收缓存为 16KB 且应用不读取数据，4 个 RTT 累计接收 1+2+4+8=15KB，故 rwnd=1KB。发送窗口=min(16KB,1KB)=1KB，选 A。",
    "steps": [
      [
        "初始 cwnd=1KB，rwnd=16KB。",
        "第 1 RTT 发送 1KB，确认后 cwnd=2KB；缓存剩余 15KB，rwnd=15KB。",
        "第 2 RTT 发送 2KB，确认后 cwnd=4KB；累计接收 3KB，rwnd=13KB。",
        "第 3 RTT 发送 4KB，确认后 cwnd=8KB；累计接收 7KB，rwnd=9KB。",
        "第 4 RTT 发送 8KB，确认后 cwnd=16KB；累计接收 15KB，rwnd=1KB。",
        "发送窗口=min(cwnd,rwnd)=min(16KB,1KB)=1KB，选 A。"
      ],
      "第 1 RTT 发送 1KB 后，rwnd=15KB，cwnd=2KB，发送窗口 2KB? 发送窗口在本 RTT 开始时为 1KB。",
      "第 2 RTT 后累计接收 3KB，rwnd=13KB，cwnd=4KB。",
      "第 3 RTT 后累计接收 7KB，rwnd=9KB，cwnd=8KB。",
      "第 4 RTT 发送 8KB 后，缓存剩余 1KB，rwnd=1KB；cwnd=16KB? 题目按每 RTT 后的窗口状态计算，发送窗口=min(cwnd,rwnd)=1KB。",
      "因此答案 A。"
    ],
