    "question": "2017-第11题-题目 下列排序方法中，若将顺序存储更换为链式存储，则算法的时间效率会降低的是（ ）。 I. 插入排序 II. 选择排序 III. 起泡排序 IV. 希尔排序 V. 堆排序 A. 仅 I、II B. 仅 II、III C. 仅 III、IV D. 仅 IV、V",
    "analysis": "插入、选择和冒泡排序在链式存储中仍可顺序扫描和调整链接，渐进时间复杂度通常不因此恶化；希尔排序需要按增量跳跃访问数组位置，堆排序依赖数组下标计算父子结点，二者依赖随机访问，改为链式存储会降低效率。选 D。",
