  "2010-42-数组循环左移三次逆置": {
    "year": 2010,
    "index": 42,
    "id": 89,
    "typeName": "应用题",
    "score": 13,
    "answer": "将数组前 p 个元素逆置，再将剩余 n−p 个元素逆置，最后将整个数组逆置，即可得到循环左移 p 位的结果。时间复杂度 O(n)，辅助空间复杂度 O(1)。",
    "question": "设将 n ( n > 1 ) 个整数存放到一维数组 R 中。试设计一个在时间和空间两方面都尽可能高效的算法。将 R 中保存的序列循环左移 p ( 0 < p < N ) 个位置，即将 R 中的数据由 < x 0 ​ , x 1 ​ , ⋯ , x n − 1 ​ > 变换为 < x p ​ , x p + 1 ​ , ⋯ , x n − 1 ​ , x 0 ​ , x 1 ​ , ⋯ , x p − 1 ​ > 。要求： (1) 给出算法的基本设计思想。 (2) 根据设计思想，采用 C 或 C++ 或 Java 语言描述，关键之处给出注释。 (3) 说明你所设计算法的时间复杂度和空间复杂度。",
    "analysis": "1）算法的基本设计思想 可以将这个问题视为把数组 ab 转换成数组 ba （ a 代表数组的前 p 个元素， b 代表数组中余下的 n − p 个元素），先将 a 逆置得到 a − 1 b , 再将 b 逆置得到 a − 1 b − 1 ，最后将整个 a − 1 b − 1 逆置得到 ( a − 1 b − 1 ) − 1 = ba 。设 Reverse 函数执行将数组元素逆置的操作，对 abcdefgh 向左循环移动 3(p=3) 个位置的过程如下： Reverse(0,p-1) 得到 cbadefgh : Reverse(p,n-l) 得到 cbahgfed ; Reverse(0,n-l) 得到 defghabc , 注：Reverse 中，两个参数分别表示数组中待转换元素的始末位置。 2）使用 C 语言描述算法如下： void reverse ( int a [], int from , int to ) { int i = from ; int j = to ; while ( i < j ) { int tmp = a [ i ]; a [ i ] = a [ j ]; a [ j ] = tmp ; i ++ ; j -- ; } } void loopMove ( int a [], int n , int p ) { if ( p < 0 ) { return ; } p = p % n ; reverse ( a , 0 , p - 1 ); reverse ( a , p , n - 1 ); reverse ( a , 0 , n - 1 ); } 3）上述算法中 3 个 Reverse 函数的时间复杂度分别为 O ( p /2 ) 、 O (( n − p ) /2 ) 和 O ( n /2 ) ，故所设计的算法的时间复杂度为 O ( n ) ，空间复杂度为 O ( 1 ) 。 【另解】借助辅助数组来实现。 算法思想：创建大小为 p 的辅助数组 S ，将 R 中前 p 个整数依次暂存在 S 中，同时将 R 中后 p 个整数左移，然后将 S 中暂存的 p 个数依次放回到 R 中的后续单元。 时间复杂度为 O ( n ) , 空间复杂度为 O ( p ) 。",
    "audit": {
      "status": "source-question-linked-teaching-solution",
      "note": "已逐题核对原始题干与原始教学解析；结构化答案由题库解析中的步骤、数值与结论整理，原始解析全文保留在 analysis 字段。"
    }
  },
  "2010-45-磁盘空闲块位图管理": {
    "year": 2010,
    "index": 45,
    "id": 92,
    "typeName": "应用题",
    "score": 7,
    "answer": "使用位图管理磁盘空闲块，每一位对应一个磁盘块；16384 个块需要 16384 bit=2048 B=2 KB。",
    "question": "假设计算机系统采用 CSCAN（循环扫描）磁盘调度策略，使用 2KB 的内存空间记录 16384 个磁盘块的空闲状态。 磁头的运动方向 100 号磁道 0 号磁道 随机分布的某扇区 (1) 请说明在上述条件如何进行磁盘块空闲状态的管理。 (2) 设某单面磁盘的旋转速度为 6000rpm，每个磁道有 100 个扇区，相邻磁道间的平均移动的时间为 1ms。若在某时刻，磁头位于 100 号磁道处，并沿着磁道号增大的方向移动（见下图），磁道号的请求队列为 50, 90, 30, 120，对请求队列中的每个磁道需读取 1 个随机分布的扇区，则读完这个扇区点共需要多少时间？需要给出计算过程。 (3) 如果将磁盘替换为随机访问的 Flash 半导体存储器（如 U 盘、SSD 等），是否有比 CSCAN 更高效的磁盘调度策略？若有，给出磁盘调度策略的名称并说明理由；若无，说明理由。",
    "analysis": "1）用 位图 表示磁盘的空闲状态。每位表示一个磁盘块的空闲状态，共需要 16384/32 = 512字 = 512×4字节 = 2KB，正好可放在系统提供的内存中。 2）采用 C-SCAN 调度算法，访问磁道的顺序和移动的磁道数见下表。 被访问的下一个磁道号 移动距离（磁道数） 120 20 30 90 50 20 90 40 移动的磁道数为 20+90+20+40 = 170，故总的移动磁道时间为 170ms。 由于转速为 6000rpm，则平均旋转延迟为 5ms，总的旋转延迟时间 = 20ms。 由于转速为 6000rpm，则读取一个磁道上一个扇区的平均读取时间为 0.1ms，总的读取扇区的时间为 0.4ms。 综上，读取上述磁道上 所有扇区所花的总时间为 190.4ms。 3）采用 FCFS 调度策略更高效。因为 Flash 半导体存储器的物理结构不需要考虑寻道时间和旋转延迟，可直接按 I/O 请求的先后顺序服务。",
    "audit": {
      "status": "source-question-linked-teaching-solution",
      "note": "已逐题核对原始题干与原始教学解析；结构化答案由题库解析中的步骤、数值与结论整理，原始解析全文保留在 analysis 字段。"
    }
  },
