    "answer": "(1) 虚拟地址 24 位，VPN 为高 12 位；物理地址 20 位，PFN 为高 8 位。(2) Cache Tag 12 位、行号 3 位、块内偏移 5 位。(3) VA 001C60H 有效，PA=04C60H，Cache 不命中。(4) VA 024BACH 的 VPN=024H，TLB 组 0 标记 012H 有效命中，页面在主存。",
