    "answer": "(1) 块号最少 4B；最大文件 128KB。(2) 原 6B 起始块号+2B 块数时，元数据容量上限为 2^16×1KB+84×1KB=65620KB。优化字段分配时建议起始块号 4B、块数 4B，使连续区可覆盖 4TB 系统容量；单个文件物理上限为 4TB。",
