    "answer": "C",
    "analysis": "转发不能消除所有数据冒险。例如Load-use冒险中，load结果到MEM阶段末才可用，而紧随其后的指令在EX阶段就需要该操作数，即使有旁路也可能需要停顿一个周期。插入气泡或调度指令可解决。",
    "steps": [
      "识别RAW相关以及数据生产者结果何时可用。",
      "算术指令结果可经EX/MEM等旁路；Load数据通常在MEM后才就绪。",
      "Load-use紧邻依赖仍可能需要停顿，故“所有冒险均可转发解决”错误，选C。"
    ],
