    "question": "【原题要点】中断I/O叙述中错误项：A中断屏蔽字确定中断响应优先级；B断点和PSW在中断响应阶段保存；C通用寄存器保存及新屏蔽字设置由软件实现；D单重中断处理期间CPU处于关中断状态。",
